import{_ as t,o as e,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Days NYC: State of the Cephalopod","description":"","frontmatter":{"title":"Ceph Days NYC: State of the Cephalopod","date":"2023-05-19T00:00:00.000Z","updated":"2023-05-20T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","可用性","扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_-_State_of_the_Cephalopod.md","filePath":"posts/2023/Ceph_Days_NYC_-_State_of_the_Cephalopod.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Days_NYC_-_State_of_the_Cephalopod.md"};function r(s,l,n,p,h,_){return e(),o("div",null,[...l[0]||(l[0]=[a('<p>会议纪要</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>会议主要讨论了Ceph项目的最新进展、未来计划以及技术特性的改进，强调了社区成员的重聚意义重大。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>社区治理模型变更</strong>：</p><ul><li>Ceph项目已从单一领导模型转变为理事会模型，由各组件负责人选举产生，负责项目的技术治理和社区管理。</li></ul></li><li><p><strong>重点发展领域</strong>：</p><ul><li><strong>质量、性能和可扩展性</strong>：加强大规模测试，改进发布流程，引入RC版本供用户测试。</li><li><strong>性能优化</strong>：特别关注Crimson项目，旨在提高性能和扩展性。</li><li><strong>用户反馈</strong>：通过Telemetry项目收集匿名数据，了解集群使用情况，优化产品。</li></ul></li><li><p><strong>版本更新</strong>：</p><ul><li>原计划于3月发布的Reef版本因实验室故障推迟至6月。</li><li>继续每年发布一个主要版本，并逐步淘汰旧版本。</li></ul></li><li><p><strong>技术特性与改进</strong>：</p><ul><li><strong>性能与扩展性</strong>：在多个大型集群上进行测试，包括澳大利亚超级计算中心。</li><li><strong>稳定性与可靠性</strong>：引入m-clock调度器，改进QoS（服务质量），优化数据平衡和客户端性能。</li><li><strong>Crimson项目</strong>：重新实现OSD，采用无共享架构，目前处于实验阶段，未来将支持更多功能。</li><li><strong>CephFS和RGW</strong>：改进用户界面，增强多站点支持和监控功能。</li></ul></li><li><p><strong>部署与管理</strong>：</p><ul><li><strong>fadm和Rook</strong>：简化部署流程，支持容器化和Kubernetes集成，增强故障诊断能力。</li></ul></li><li><p><strong>RBD和RGW的进一步优化</strong>：</p><ul><li><strong>RBD</strong>：增强多站点镜像功能，支持高性能协议如NVMe-oF。</li><li><strong>RGW</strong>：优化多站点复制性能，引入OpenTelemetry进行分布式追踪。</li></ul></li><li><p><strong>测试与质量保证</strong>：</p><ul><li>改善开发者体验，优化本地测试环境，增强实验室基础设施的韧性。</li><li>探索与其他组织合作，共享硬件资源，提高测试效率。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>Reef版本的发布推迟至6月。</li><li>继续推进性能、质量和可用性的改进。</li><li>加强社区合作，优化测试和开发环境。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>完成Reef版本的开发和测试，确保按时发布。</li><li>持续优化Crimson项目，提升其稳定性和性能。</li><li>加强与社区成员的沟通，收集反馈，持续改进产品。</li></ul><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><ul><li>会议中还讨论了QoS的细粒度控制，未来将支持基于图像级别的策略配置。</li></ul>',11)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
